import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { Link } from 'react-router-dom';

const Dashboard = () => {
  const [user, setUser] = useState(null);
  const [repos, setRepos] = useState([]);
  const [autoReviewMap, setAutoReviewMap] = useState({});

  // 1. Fetch logged-in user
  useEffect(() => {
    axios.get('http://localhost:5000/api/user', { withCredentials: true })
      .then(res => setUser(res.data.user))
      .catch(() => window.location.href = '/');
  }, []);

  // 2. Only after user is loaded, fetch repos and auto-review
  useEffect(() => {
    if (!user) return;

    // Determine provider
    const provider = user.provider || 'github';

    // Fetch repos
    const repoApi = provider === 'gitlab'
      ? '/api/gitlab/repos'
      : '/api/github/repos';

    axios.get(`http://localhost:5000${repoApi}`, { withCredentials: true })
      .then(res => setRepos(res.data))
      .catch(err => console.error("Fetch repos failed:", err));

    // Fetch auto-review settings
    axios.get('http://localhost:5000/api/repo/auto-review', { withCredentials: true })
      .then(res => setAutoReviewMap(res.data))
      .catch(err => console.error("Fetch auto-review settings failed:", err));
  }, [user]);

  // 3. Toggle function, using correct provider
  const toggleAutoReview = (repoName, currentStatus) => {
    const newStatus = !currentStatus;
    const provider = user.provider || 'github';

    axios.post('http://localhost:5000/api/repo/auto-review', {
      repoName,
      provider,
      autoReview: newStatus
    }, { withCredentials: true })
      .then(() => {
        setAutoReviewMap(prev => ({ ...prev, [repoName]: newStatus }));
      })
      .catch(err => console.error("Toggle failed:", err));
  };

  if (!user) return <p>Loading user...</p>;

  return (
    <div style={{ padding: '2rem' }}>
      <h2>Welcome, {user.displayName}</h2>
      <img src={user.photos?.[0]?.value} alt="Avatar" width={80} />
      <p><strong>User:</strong> {user.username} ({user.provider})</p>

      <h3>Your Repositories:</h3>
     
      <ul>
  {repos.map((repo) => (
    <li key={repo.name}>
      <strong>{repo.name}</strong> | ⭐ {repo.stars} | Branch: {repo.default_branch}
      <button onClick={() => toggleAutoReview(repo.name, autoReviewMap[repo.name])}>
        {autoReviewMap[repo.name] ? 'Disable Auto Review' : 'Enable Auto Review'}
      </button>
      <Link to={`/repo/${repo.name}`} style={{ marginLeft: '1rem' }}>
        View Details
      </Link>
    </li>
  ))}
</ul>

      
    </div>
  );
};

export default Dashboard;
